parameters.jsCode:
const body = $input.first().json.body;
return [{
  json: {
    email: body.email,
    name: body.name,
    org_id: body.org_id,
    plan: body.plan || 'free',
    created_at: new Date().toISOString()
  }
}];

const body = $input.first().json.body;
const tier = body.tier || 'free';
let features = {};

if (tier === 'free') {
  features = {
    max_portfolios: 3,
    max_optimizations: 5,
    api_access: false,
    priority_support: false,
    market_data: false
  };
} else if (tier === 'pro') {
  features = {
    max_portfolios: 50,
    max_optimizations: 500,
    api_access: true,
    priority_support: false,
    market_data: true
  };
} else if (tier === 'enterprise') {
  features = {
    max_portfolios: -1,
    max_optimizations: -1,
    api_access: true,
    priority_support: true,
    market_data: true
  };
}

return [{
  json: {
    org_id: body.org_id,
    tier,
    features
  }
}];

const input = $input.first().json;
const body = {
  subject: `Welcome to Quantive, ${input.name}!`,
  to: input.email,
  template: 'welcome',
  data: {
    loginUrl: `${input.loginUrl || 'https://app.quantive.io'}`,
    quickStartGuide: `${input.baseUrl || 'https://app.quantive.io'}/docs/quick-start`,
    supportContact: 'support@quantive.io',
    videoUrl: `${input.baseUrl || 'https://app.quantive.io'}/docs/getting-started`
  }
};
return [{ json: body }];

const input = $input.first().json;
return [{
  json: {
    to: input.to,
    subject: 'How to Get Started with Quantive',
    loginUrl: input.loginUrl || 'https://app.quantive.io',
    apiTokenUrl: input.baseUrl ? `${input.baseUrl}/settings/api-tokens` : 'https://app.quantive.io/settings/api-tokens',
    twoFactorUrl: input.baseUrl ? `${input.baseUrl}/settings/security` : 'https://app.quantive.io/settings/security',
    passwordTips: [
      'Use at least 12 characters',
      'Include uppercase and lowercase letters',
      'Add numbers and special characters',
      'Don\'t reuse passwords from other sites'
    ]
  }
}];

const input = $input.first().json;
const step = input.step || 1;
const steps = {
  1: {
    subject: 'Create Your First Portfolio',
    guide: 'portfolio-creation'
  },
  2: {
    subject: 'Import Your Data with CSV',
    guide: 'csv-import'
  },
  3: {
    subject: 'Run Your First Optimization',
    guide: 'first-optimization'
  },
  4: {
    subject: 'Explore Your Risk Dashboard',
    guide: 'risk-dashboard'
  },
  5: {
    subject: 'Set Up Automated Reports',
    guide: 'reporting-setup'
  }
};
return [{
  json: {
    ...input,
    currentStep: step,
    stepData: steps[step] || steps[1],
    baseUrl: input.baseUrl || 'https://app.quantive.io'
  }
}];

const input = $input.first().json;
const nextStep = input.step + 1;
return [{
  json: {
    completed: nextStep >= 5,
    org_id: input.org_id
  }
}];

const portfolios = $input.first().json.body || $input.first().json;
optimizations = $input.last().json.body || $input.last().json;

const metrics = [];
const orgMap = {};

if (Array.isArray(portfolios)) {
  for (const p of portfolios) {
    if (!orgMap[p.org_id]) orgMap[p.org_id] = { portfolios: 0, optimizations: 0 };
    orgMap[p.org_id].portfolios++;
  }
}

if (Array.isArray(optimizations)) {
  for (const o of optimizations) {
    if (!orgMap[o.org_id]) orgMap[o.org_id] = { portfolios: 0, optimizations: 0 };
    orgMap[o.org_id].optimizations++;
  }
}

for (const [org_id, data] of Object.entries(orgMap)) {
  metrics.push({
    json: {
      org_id,
      portfolios_created: data.portfolios,
      optimizations_run: data.optimizations,
      api_calls: data.optimizations * 10,
      storage_used_mb: data.portfolios * 2.5,
      measured_at: new Date().toISOString()
    }
  });
}

return metrics;

const input = $input.first().json;
const daysInactive = input.days_inactive || 0;
let emailType = '7-day';

if (daysInactive > 30) {
  emailType = '30-day-offer';
} else if (daysInactive > 14) {
  emailType = '14-day-features';
} else if (daysInactive > 7) {
  emailType = '7-day-miss-you';
}

return [{
  json: {
    ...input,
    emailType,
    daysInactive
  }
}];

const body = $input.first().json.body;
return [{
  json: {
    request_id: body.request_id || 'req_' + Date.now(),
    email: body.email,
    name: body.name,
    message: body.message,
    type: body.type || 'general',
    org_id: body.org_id,
    created_at: new Date().toISOString()
  }
}];

const input = $input.first().json;
const faqResults = input.faqResults || [];
const message = input.message.toLowerCase();

const faqDatabase = [
  {
    question: 'How do I reset my password?',
    answer: 'Go to Settings > Security > Change Password. You can also use the Forgot Password link on the login page.',
    category: 'account'
  },
  {
    question: 'How do I create a portfolio?',
    answer: 'Navigate to Portfolios > New Portfolio. Follow the guided wizard to set up your sovereign debt portfolio.',
    category: 'portfolio'
  },
  {
    question: 'How do I run an optimization?',
    answer: 'Go to Optimizations > New Optimization. Select your portfolio and choose your optimization strategy.',
    category: 'optimization'
  },
  {
    question: 'How do I import CSV data?',
    answer: 'Go to Portfolios > Import. Download our CSV template, fill in your data, and upload.',
    category: 'data'
  },
  {
    question: 'How do I cancel my subscription?',
    answer: 'Go to Billing > Subscription > Cancel. You can continue using the service until the end of your billing period.',
    category: 'billing'
  }
];

let bestMatch = null;
let bestScore = 0;

for (const faq of faqDatabase) {
  const faqLower = faq.question.toLowerCase();
  let score = 0;
  const words = message.split(' ');
  for (const word of words) {
    if (faqLower.includes(word)) score++;
  }
  const normalizedScore = score / words.length;
  if (normalizedScore > bestScore) {
    bestScore = normalizedScore;
    bestMatch = faq;
  }
}

return [{
  json: {
    ...input,
    bestMatch,
    confidence: bestScore,
    response: bestMatch ? bestMatch.answer : 'Thank you for your question. Our support team will get back to you shortly.',
    escalated: bestScore < 0.8
  }
}];

const body = $input.first().json.body;
return [{
  json: {
    ticket_id: body.ticket_id,
    subject: body.subject,
    description: body.description,
    email: body.email,
    org_id: body.org_id,
    tier: body.tier || 'free',
    created_at: new Date().toISOString()
  }
}];

const input = $input.first().json;
const subject = (input.subject || '').toLowerCase();
const description = (input.description || '').toLowerCase();
const text = subject + ' ' + description;

let category = 'question';
if (text.includes('bug') || text.includes('error') || text.includes('crash') || text.includes('broken')) {
  category = 'bug';
} else if (text.includes('feature') || text.includes('request') || text.includes('suggestion')) {
  category = 'feature';
} else if (text.includes('billing') || text.includes('charge') || text.includes('payment') || text.includes('invoice')) {
  category = 'billing';
}

return [{
  json: {
    ...input,
    category
  }
}];

