const body = $input.first().json.body;
return [{
  json: {
    bug_id: body.bug_id || 'bug_' + Date.now(),
    title: body.title,
    description: body.description,
    steps_to_reproduce: body.steps_to_reproduce || [],
    expected_behavior: body.expected_behavior,
    actual_behavior: body.actual_behavior,
    severity: body.severity || 'medium',
    reporter_email: body.reporter_email,
    reporter_name: body.reporter_name,
    created_at: new Date().toISOString()
  }
}];

const input = $input.first().json;
const title = input.title.toLowerCase();
const description = (input.description || '').toLowerCase();

// Simple duplicate detection based on title similarity
const keywords = title.split(' ').filter(w => w.length > 3);

return [{
  json: {
    ...input,
    isDuplicate: false,
    searchTerms: keywords.join(' | ')
  }
}];

const body = $input.first().json.body;
return [{
  json: {
    request_id: body.request_id || 'pay_' + Date.now(),
    type: body.type || 'question',
    email: body.email,
    name: body.name,
    org_id: body.org_id,
    amount: body.amount,
    reason: body.reason,
    created_at: new Date().toISOString()
  }
}];

const input = $input.first().json;
const eligible = input.amount <= 100 && input.reason;

return [{
  json: {
    ...input,
    eligible,
    refundAmount: eligible ? input.amount : 0
  }
}];

const input = $input.first().json;
return [{
  json: {
    ...input,
    evidence: {
      customer_email: input.email,
      reason: input.reason,
      dispute_date: new Date().toISOString()
    }
  }
}];

const input = $input.first().json;
const currentPlanPrice = 49;
const newPlanPrice = 99;
const daysRemaining = 15;
const proration = ((newPlanPrice - currentPlanPrice) / 30) * daysRemaining;

return [{
  json: {
    ...input,
    proration: Math.round(proration * 100) / 100,
    currentPlanPrice,
    newPlanPrice,
    daysRemaining
  }
}];

const input = $input.first().json;
return [{
  json: {
    ...input,
    billingSummary: {
      currentPlan: 'Pro',
      nextBillingDate: '2024-02-01',
      amount: 99.00,
      paymentMethod: 'Visa ending in 4242'
    }
  }
}];

const input = $input.first().json;
const now = new Date();
const ticketAge = now - new Date(input.created_at);
const hoursOld = ticketAge / (1000 * 60 * 60);

const shouldEscalate = (
  (hoursOld > 24 && input.priority === 'high') ||
  (input.tier === 'enterprise') ||
  (input.type === 'payment')
);

let urgency = 'normal';
if (hoursOld > 24 && input.priority === 'high') urgency = 'time-sensitive';
if (input.tier === 'enterprise') urgency = 'enterprise-priority';
if (input.type === 'payment') urgency = 'payment-urgent';

return [{
  json: {
    ...input,
    shouldEscalate,
    urgency,
    hoursOld: Math.round(hoursOld)
  }
}];

